def _run_build_awareness_candidates(
    transcripts_dir: Path,
    output_dir: Path,
    cwd: Path | None = None,
) -> None:
    root = cwd or Path(__file__).resolve().parents[1]
    cmd = [
        sys.executable,
        "-m",
        "scripts.build_awareness_candidates",
        "-i",
        str(transcripts_dir),
        "-o",
        str(output_dir),
        "--allow-no-enchant",
    ]
    result = subprocess.run(  # noqa: S603
        cmd,
        capture_output=True,
        text=True,
        cwd=root,
        check=False,
    )
    assert result.returncode == 0, (result.stdout, result.stderr)


def test_build_awareness_candidates_output_has_unified_schema_no_corrections(
    tmp_path: Path,
) -> None:
    """Run build_awareness_candidates on fixture; assert output has rule_id, span, corrections: [], occurrences with path, line_num, start_index."""
    transcripts_dir = tmp_path / "transcripts"
    transcripts_dir.mkdir()
    fixture = transcripts_dir / "sample" / "oral_argument.json"
    fixture.parent.mkdir(parents=True)
    # Fixture: non-ASCII (é), mixed-case (McCloud), bracket [cough], H1N1, symbol …
    fixture.write_text(
        json.dumps(
            {
                "metadata": {},
                "turns": [
                    {
                        "index": 0,
                        "text": "Calf\u00e9 and McCloud [cough] H1N1 virus\u2026",
                    },
                ],
            },
            indent=2,
        )
    )
    out_dir = tmp_path / "out"
    out_dir.mkdir()
    _run_build_awareness_candidates(
        transcripts_dir, out_dir, cwd=Path(__file__).resolve().parents[1]
    )

    out_files = list(out_dir.iterdir())
    assert out_files, out_files
    # At least one awareness file (e.g. awareness_mixed_case_candidates.json)
    any_awareness = any(
        f.name.startswith("awareness_") and f.name.endswith("_candidates.json")
        for f in out_files
    )
    assert any_awareness, [f.name for f in out_files]

    # Pick a file that should exist (mixed_case is in fixture)
    mixed_path = out_dir / "awareness_mixed_case_candidates.json"
    assert mixed_path.exists(), [f.name for f in out_files]
    data = json.loads(mixed_path.read_text())
    assert data.get("rule_id") == "awareness_mixed_case"
    assert "rule_name" in data
    assert "filter_note" in data
    candidates = data.get("candidates", [])
    assert candidates
    c = candidates[0]
    assert "span" in c
    assert c.get("corrections") == []
    assert "occurrences" in c
    for occ in c["occurrences"]:
        assert "path" in occ
        assert "line_num" in occ
        assert "start_index" in occ


# Plan: awareness non-dictionary
def test_build_awareness_candidates_non_dictionary(tmp_path: Path) -> None:
    """Transcript with befair, supremecourt, the18th produces awareness_non_dictionary; the, court do not."""
    transcripts_dir = tmp_path / "transcripts"
    transcripts_dir.mkdir()
    fixture = transcripts_dir / "sample" / "oral_argument.json"
    fixture.parent.mkdir(parents=True)
    fixture.write_text(
        json.dumps(
            {
                "metadata": {},
                "turns": [
                    {
                        "index": 0,
                        "text": "the court befair supremecourt the18th June22nd",
                    },
                ],
            },
            indent=2,
        )
    )
    out_dir = tmp_path / "out"
    out_dir.mkdir()
    _run_build_awareness_candidates(
        transcripts_dir, out_dir, cwd=Path(__file__).resolve().parents[1]
    )
    path = out_dir / "awareness_non_dictionary_candidates.json"
    assert path.exists(), list(out_dir.iterdir())
    data = json.loads(path.read_text())
    candidates = data.get("candidates", [])
    spans = [c.get("span") for c in candidates]
    assert "befair" in spans, spans
    assert "supremecourt" in spans, spans
    assert "the" not in spans, spans
    assert "court" not in spans, spans
    assert "the18th" in spans, spans
    # Awareness does not suggest corrections; split "the 18th" comes from rule concatenated_word_split.
    cand_18 = next(c for c in candidates if c.get("span") == "the18th")
    assert cand_18.get("corrections") == [], cand_18.get("corrections")


